(() => {
'use strict';
const dialog=document.querySelector('#overlay'), panel=document.querySelector('#panel'), scene=document.querySelector('#scene');
let category='all', query='', lastFocus=null;
const labels={all:'전체',journal:'일상',places:'장소',finds:'발견',notes:'메모'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function position(){const w=scene.clientWidth,h=scene.clientHeight,scale=Math.max(w/1536,h/1024),offsetX=(w-1536*scale)*(w<=650?.48:.5),offsetY=(h-1024*scale)/2;document.querySelectorAll('.spot').forEach(el=>{el.style.left=(Number(el.dataset.x)*scale+offsetX)+'px';el.style.top=(Number(el.dataset.y)*scale+offsetY)+'px';});}
window.addEventListener('resize',position);position();
document.querySelectorAll('[data-target]').forEach(el=>el.addEventListener('click',()=>location.hash=el.dataset.target));
function entries(){const filtered=window.POSTS.filter(p=>(category==='all'||p.category===category)&&[p.title,p.excerpt,...p.body].join(' ').toLowerCase().includes(query.toLowerCase()));document.querySelector('#entries').innerHTML=filtered.length?filtered.map((p,i)=>`<a class="entry" href="#post/${escape(p.id)}"><span class="number">0${i+1}</span><div><small>${escape(labels[p.category])} / ${escape(p.date)}${p.sample?' / SAMPLE':''}</small><h2>${escape(p.title)}</h2><p>${escape(p.excerpt)}</p></div><span class="arrow" aria-hidden="true">↗</span></a>`).join(''):'<p class="empty">아직 발견하지 못했어요. 다른 단어로 찾아보세요.</p>';document.querySelector('#count').textContent=`${filtered.length}개의 기록`;}
function archive(){panel.innerHTML=`<p class="eyebrow">THE COLLECTED THINGS / 001</p><h1 id="panel-title">모아 둔<br><i>기록들.</i></h1><p class="intro">지나온 곳과 좋아하는 것, 그리고 가끔의 생각.<br>마음이 가는 곳부터 읽어보세요.</p><label><span class="sr-label">기록 검색</span><input class="search" type="search" placeholder="어떤 기록을 찾고 있나요?" aria-label="기록 검색" value="${escape(query)}"></label><div class="filters" aria-label="분류">${Object.entries(labels).map(([id,label])=>`<button class="filter ${category===id?'active':''}" data-category="${id}" aria-pressed="${category===id}">${label}</button>`).join('')}</div><div id="entries"></div><p class="count" id="count" aria-live="polite"></p>`;panel.querySelector('.sr-label').style.cssText='position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)';entries();panel.querySelector('input').addEventListener('input',e=>{query=e.target.value;entries();});panel.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;panel.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});entries();}));}
function article(id){const p=window.POSTS.find(p=>p.id===id);if(!p){panel.innerHTML='<p class="eyebrow">404 / LOST & FOUND</p><h1 id="panel-title">길을 조금<br>벗어났네요.</h1><a class="backlink" href="#archive">모든 기록으로 ↗</a>';return;}panel.innerHTML=`<p class="eyebrow">${escape(labels[p.category])} / SOMETHING WORTH KEEPING</p>${p.sample?'<span class="sample">SAMPLE — 디자인 확인용 예시 글</span>':''}<h1 id="panel-title">${escape(p.title)}</h1><p class="article-meta">${escape(p.date)} · b.log</p><article class="article-body">${p.body.map((t,i)=>`<p class="${i===0?'lead':''}">${escape(t)}</p>`).join('')}</article><a class="backlink" href="#archive">↖ 모아 둔 기록들</a>`;}
function route(){const hash=location.hash.slice(1);if(!hash){if(dialog.open)dialog.close();document.title='b.log — somewhere';return;}if(!dialog.open){lastFocus=document.activeElement;dialog.showModal();}if(hash==='archive')archive();else if(hash==='about')panel.innerHTML='<p class="eyebrow">A PERSONAL SPACE / B.LOG</p><h1 id="panel-title">여기는,<br><i>어딘가.</i></h1><p class="intro">발길이 닿은 곳.<br>마음에 걸린 생각.<br>그냥 지나치기 아쉬웠던 작은 발견들.</p><div class="about-symbol" aria-hidden="true">✳</div><p class="intro">사진 속을 천천히 둘러보세요.<br>파란 매듭에는 이야기 하나,<br>귤에는 짧은 메모가 숨어 있어요.</p><p class="about-note">이 공간에 실린 글은 디자인 확인을 위한 샘플입니다.<br>메인 이미지는 이 블로그를 위해 AI로 제작했습니다.</p><a class="backlink" href="#archive">기록 구경하기 ↗</a>';else if(hash.startsWith('post/'))article(hash.slice(5));else{location.replace('#archive');return;}dialog.scrollTop=0;document.title=`${panel.querySelector('h1').textContent} — b.log`;}
function close(){history.replaceState(null,'',location.pathname+location.search);dialog.close();document.title='b.log — somewhere';if(lastFocus&&lastFocus.isConnected)lastFocus.focus();}
document.querySelector('#close').addEventListener('click',close);document.querySelector('.home').addEventListener('click',e=>{e.preventDefault();close();});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)close();});window.addEventListener('hashchange',route);route();
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();if(location.hash==='#archive')panel.querySelector('input').focus();else{location.hash='archive';setTimeout(()=>panel.querySelector('input')?.focus(),0);}}});
})();
